"""A5 beyond the catalog: bottom-lift certificates for Bremner family members with
L_1 > 10^12 (both twin forms), seeds that no exhaustive search reaches.
Usage: ~/sage_venv/bin/python -u certify_families.py [tries]
"""
import sys
import time

import json

from lift_pipeline import certify_seed

# seeds generated by the system python (code/old/utils.py needs tqdm):
#   family 1, k = 2, 3, 4 and family 2, k = 8, 9, 10, both twin forms -> family_seeds.json
tries = int(sys.argv[1]) if len(sys.argv) > 1 else 80
for label, rho in json.load(open('family_seeds.json')).items():
    if True:
        name, form = label.split()
        t0 = time.time()
        res = certify_seed(rho, tries=tries, verbose=False)
        dt = time.time() - t0
        tag = f'{name:>6} {form:>4} (max root {max(rho)})'
        print(f'{tag}: ' + (f'CERTIFIED no E_5 above (quotient {res[0]}, p0 = {res[1]}; {dt:.0f} s)'
                              if res else f'undecided after {tries} subsets ({dt:.0f} s)'), flush=True)
